INSERT INTO `categories` VALUES (1,NULL,'Nilgiri Teas','nilgiri-teas','High-grown estate teas with the bright, brisk character the Nilgiris are known for.','/uploads/content/category-nilgiri-teas.webp',1,1,'2026-11-10 10:16:05'),(2,NULL,'Coffee','coffee','Rich, aromatic coffee from the hills — filter blends and instant.','/uploads/content/category-coffee.webp',2,1,'2026-11-10 10:16:05'),(3,NULL,'Homemade Chocolates','homemade-chocolates','Ooty’s famous homemade chocolates, made fresh in small batches.','/uploads/content/category-homemade-chocolates.webp',3,1,'2026-11-10 10:16:05'),(4,NULL,'Cookies & Bakes','cookies-bakes','Crisp Ooty varkey and wheat biscuits, baked the traditional way.','/uploads/content/category-cookies-bakes.webp',4,1,'2026-11-10 10:16:05'),(5,NULL,'Essential Oils','essential-oils','Pure, steam-distilled oils from the Nilgiri hills.','/uploads/content/category-essential-oils.webp',5,1,'2026-11-10 10:16:05'),(6,NULL,'Nilgiri Jams','nilgiri-jams','Fruit jams made from hill-grown produce.','/uploads/products/pineapple-fruit-jam-1.webp',6,1,'2026-11-10 10:16:05'),(7,NULL,'Honey','honey','Raw forest honey gathered in the Nilgiris.','/uploads/products/nilgiri-forest-honey-wild-bitter-1.webp',7,1,'2026-11-10 10:16:05'),(8,NULL,'Spices','spices','Whole spices with full aroma — pepper, cardamom, cloves and cinnamon.','/uploads/products/cinnamon-100g-1.webp',8,1,'2026-11-10 10:16:05'),(9,NULL,'Nuts','nuts','Premium nuts, carefully graded and freshly packed.','/uploads/products/roasted-pista-premium-1.webp',9,1,'2026-11-10 10:16:05'),(10,NULL,'Dried Fruits','dried-fruits','Naturally sweet dried fruits for everyday snacking.','/uploads/products/raisins-dry-grapes-1.webp',10,1,'2026-11-10 10:16:05'),(11,NULL,'Gift Hampers','gift-hampers','Curated hampers that bring the best of Ooty together.','/uploads/products/ooty-s-finest-five-tea-time-hamper-1.webp',11,1,'2026-11-10 10:16:05'),(12,5,'Oils','oils','Single-origin essential and carrier oils.','/uploads/products/eucalyptus-oil-1.webp',1,1,'2026-11-10 10:16:05'),(13,5,'Roll-ons','roll-ons','Easy-to-carry roll-on blends.','/uploads/products/migraine-oil-roll-on-1.webp',2,1,'2026-11-10 10:16:05'),(14,5,'Sprays','sprays','Ready-to-use natural sprays.','/uploads/products/lemongrass-oil-spray-1.webp',3,1,'2026-11-10 10:16:05'),(15,5,'Combos','oil-combos','Value sets of our most-loved oils.','/uploads/products/eucalyptus-oil-roll-on-set-of-3-combo-1.webp',4,1,'2026-11-10 10:16:05');
