LOCK TABLES `products` WRITE;
/*!40000 ALTER TABLE `products` DISABLE KEYS */;
INSERT INTO `products` VALUES (1,1,NULL,'Nilgiri Cardamom Tea 200g','nilgiri-cardamom-tea-200g',NULL,'Indulge in the refreshing taste of Nilgiri Cardamom Tea from our Online Ooty Store. This tea is the perfect blend of natural tea leaves and a blast of cardamom, also known as elaichi tea. It is rejuvenating and free from any artificial flavors, making it a perfect choice for tea lovers who want to enjoy the natural taste of tea. Our Nilgiri Cardamom Tea is made with the best quality tea leaves from Nilgiris, ensuring that you get the best Ooty products. Get your hands on this delightful tea today!','<p>Indulge in the refreshing taste of Nilgiri Cardamom Tea from our Online Ooty Store. This tea is the perfect blend of natural tea leaves and a blast of cardamom, also known as elaichi tea. It is rejuvenating and free from any artificial flavors, making it a perfect choice for tea lovers who want to enjoy the natural taste of tea.</p>\n<p>Our Nilgiri Cardamom Tea is made with the best quality tea leaves from Nilgiris, ensuring that you get the best Ooty products. Get your hands on this delightful tea today!</p>','[{\"label\":\"Net quantity\",\"value\":\"200g\"},{\"label\":\"Category\",\"value\":\"Nilgiri Teas\"},{\"label\":\"Packed & shipped from\",\"value\":\"Ooty, The Nilgiris\"},{\"label\":\"Price\",\"value\":\"Inclusive of GST\"}]','Tea',200.00,225.00,40,1,0,0,0,'2026-11-10 10:16:05','2026-11-10 10:16:05'),(2,1,NULL,'Nilgiri Ginger Tea 200g','nilgiri-ginger-tea-200g',NULL,'Ginger is known to aid in digestive issues and can help lower blood pressure, while green tea is rich in antioxidants and can boost immunity. This 200g pack is perfect for tea lovers who want to indulge in a healthy and refreshing beverage. Order now from our online Ooty store and enjoy the taste of the Nilgiris in every sip.','<p>Experience the soothing and fresh taste of our Nilgiri Ginger Tea. Made with premium quality Nilgiri green tea and infused with natural ginger, this tea is not only delicious but also has numerous health benefits.</p>','[{\"label\":\"Net quantity\",\"value\":\"200g\"},{\"label\":\"Category\",\"value\":\"Nilgiri Teas\"},{\"label\":\"Packed & shipped from\",\"value\":\"Ooty, The Nilgiris\"},{\"label\":\"Price\",\"value\":\"Inclusive of GST\"}]',NULL,200.00,225.00,40,1,0,0,0,'2026-11-10 10:16:05','2026-11-10 10:16:05'),(3,1,NULL,'Nilgiri Masala Tea 200g','nilgiri-masala-tea-200g',NULL,'The health benefits of this tea are endless, including improved digestion and reduced inflammation. Proudly made in Ooty, India, this Nilgiri Masala Tea is a must-try for tea enthusiasts everywhere. Each pack contains 200g of high-quality tea.','<p>Our Nilgiri Masala Tea, also known as masala chai, is a blend of 9 carefully selected ingredients that create a rich and flavorful tea. Made with premium nilgiri tea, this tea offers a unique taste that is both strong and refreshing.</p>','[{\"label\":\"Net quantity\",\"value\":\"200g\"},{\"label\":\"Category\",\"value\":\"Nilgiri Teas\"},{\"label\":\"Packed & shipped from\",\"value\":\"Ooty, The Nilgiris\"},{\"label\":\"Price\",\"value\":\"Inclusive of GST\"}]',NULL,200.00,225.00,40,1,0,0,0,'2026-11-10 10:16:05','2026-11-10 12:46:05'),(4,1,NULL,'Nilgiri Black Tea 150g','nilgiri-black-tea-150g',NULL,'Rich in antioxidants, this tea promotes overall health and well-being. With its unique aroma and taste, Nilgiri tea is a must-try for all tea lovers. Get your hands on this exquisite tea today and experience the taste of Ooty','<p>Our Nilgiri Black Tea 150g is a premium quality whole leaf black tea sourced from the renowned Nilgiri tea gardens. This orthodox tea is made from whole leaves, ensuring maximum flavor and health benefits.</p>','[{\"label\":\"Net quantity\",\"value\":\"150g\"},{\"label\":\"Category\",\"value\":\"Nilgiri Teas\"},{\"label\":\"Packed & shipped from\",\"value\":\"Ooty, The Nilgiris\"},{\"label\":\"Price\",\"value\":\"Inclusive of GST\"}]',NULL,150.00,200.00,40,1,0,0,0,'2026-11-10 10:16:05','2026-11-10 10:16:05'),(5,1,NULL,'Nilgiri Green Tea 150g','nilgiri-green-tea-150g',NULL,'How to use Apply 2g (approx 4-5 leaves) to cup of hot water and brew for 5mins Add sugar for taste and Not Milk!','<p>Whole Leaf Green Tea is produced in orthodox methods by specialty tea factories across The Nilgiris.</p>\n<p><strong>Benefits of Green Tea</strong></p>\n<p>– Rich in antioxidants<br />\n– Supports brain health<br />\n– Support weight management<br />\n– Protects against cancer<br />\n– Immunity<br />\n– Bone density<br />\n– Helps balance blood sugar and prevent diabetes<br />\n– Supports heart health<br />\n– Protects skin from aging</p>','[{\"label\":\"Net quantity\",\"value\":\"150g\"},{\"label\":\"Category\",\"value\":\"Nilgiri Teas\"},{\"label\":\"Packed & shipped from\",\"value\":\"Ooty, The Nilgiris\"},{\"label\":\"Price\",\"value\":\"Inclusive of GST\"}]',NULL,165.00,215.00,40,1,0,0,0,'2026-11-10 10:16:05','2026-11-10 10:16:05'),(6,1,NULL,'Nilgiri Natural Super Premium Tea','nilgiri-natural-super-premium-tea',NULL,'Unlike other teas, this blend contains no artificial flavors or additives, making it a truly natural and healthy choice. Enjoy the premium quality and taste of Nilgiri Natural Super Premium Tea 500g pack today.','<p>Indulge in the authentic taste of Nilgiri Natural Super Premium Tea. Sourced from the Ooty tea factory, this tea is made from the finest Nilgiri natural tea leaves, ensuring a rich and flavorful brew.</p>','[{\"label\":\"Category\",\"value\":\"Nilgiri Teas\"},{\"label\":\"Packed & shipped from\",\"value\":\"Ooty, The Nilgiris\"},{\"label\":\"Price\",\"value\":\"Inclusive of GST\"}]',NULL,240.00,280.00,40,1,0,0,0,'2026-11-10 10:16:05','2026-11-10 10:16:05'),(7,2,NULL,'Instant Coffee Classic 200g','instant-coffee-classic-200g',NULL,'The addition of Instant Coffee Spray Powder ensures that the coffee dissolves easily and blends perfectly with milk or water.With 30% chicory, this classic blend guarantees a balanced and smooth taste that will keep you coming back for more. Treat yourself to a delicious cup of coffee anytime, anywhere with our Instant Coffee Classic. Strong Flavor Coffee – 70% Chicory – 30%','<p>Indulge in the rich aroma and taste of our Instant Coffee Classic. Made from the finest coffee beans, this instant coffee powder is perfect for those who want a quick and easy cup of coffee without compromising on taste.</p>\n<p>This is high quality instant coffee powder with 70% Coffee and 30% Chicory.</p>','[{\"label\":\"Available weights\",\"value\":\"200g\"},{\"label\":\"Category\",\"value\":\"Coffee\"},{\"label\":\"Packed & shipped from\",\"value\":\"Ooty, The Nilgiris\"},{\"label\":\"Price\",\"value\":\"Inclusive of GST\"}]',NULL,250.00,280.00,40,1,0,0,0,'2026-11-10 10:16:05','2026-11-10 10:16:05'),(8,2,NULL,'Instant Coffee 100g','instant-coffee-100g',NULL,'Whether you’re in a rush in the morning or need a quick pick-me-up during the day, our Instant Coffee is the perfect solution. Simply add hot water and enjoy with sugar if needed.','<p>Looking for a quick and convenient way to enjoy a delicious cup of coffee? Look no further than our Instant Coffee! Made from a blend of 70% coffee and 30% chicory, this unflavoured powder is perfect for those who prefer their coffee strong and aromatic.</p>\n<p>This is High quality Pack of 100g of Instant Coffee Granules.</p>','[{\"label\":\"Net quantity\",\"value\":\"100g\"},{\"label\":\"Category\",\"value\":\"Coffee\"},{\"label\":\"Packed & shipped from\",\"value\":\"Ooty, The Nilgiris\"},{\"label\":\"Price\",\"value\":\"Inclusive of GST\"}]',NULL,250.00,280.00,40,1,0,0,0,'2026-11-10 10:16:05','2026-11-10 10:16:05'),(9,5,12,'Migraine Oil','migraine-oil',NULL,'A powerful blend of essential oils in a convenient roll-on stick also in the bottle for instant migraine and headache relief. Pocket-sized, pocket-friendly, and 100% natural. Best Seller at Ooty Originals','<h4>About This Product</h4>\n<p>The Ooty Originals Migraine Oil is a therapeutic blend of essential oils — including peppermint, lavender, and eucalyptus — formulated specifically to relieve the debilitating symptoms of migraines, tension headaches, and nausea.</p>\n<h4>Key Benefits</h4>\n<ul>\n<li>Relieves migraine and headache pain fast</li>\n<li>Reduces nausea commonly associated with migraines</li>\n<li>Calms the mind and reduces stress — a key migraine trigger</li>\n<li>Improves sleep quality, helping prevent stress-induced migraines</li>\n<li>Portable roll-on format — apply anytime, anywhere</li>\n<li>100% natural — no synthetic drugs or chemicals</li>\n</ul>\n<h4>How to Use / How to Apply</h4>\n<ul>\n<li>Apply roll-on/oil to both temples and gently massage in circular motion.</li>\n<li>Roll across the forehead and back of the neck for tension relief.</li>\n<li>Breathe in the aroma deeply for 30–60 seconds for nausea relief.</li>\n<li>Apply to wrists for a subtle, continuous calming effect.</li>\n<li>Use at the first sign of a migraine for best results.</li>\n</ul>\n<h4>How It Works</h4>\n<p>The formulation combines the cooling analgesic effect of peppermint (menthol blocks pain receptors), the calming anxiolytic properties of lavender, and the decongestant benefits of eucalyptus oil. Together, they address the four main migraine triggers: pain, nausea, stress, and sensory overload — all through topical absorption and aroma inhalation.</p>\n<h4>Why Buy From Us?</h4>\n<ul>\n<li>Specifically formulated for migraine relief — not just a generic roll-on</li>\n<li>Best Seller at Ooty Originals with high repeat purchase rate</li>\n<li>All-natural ingredients — no parabens, no alcohol, no synthetic fragrance</li>\n<li>Slim, pocket-friendly design — fits in any bag</li>\n<li>Priced at just ₹150 — most affordable natural migraine remedy online</li>\n</ul>\n<h4>Who Can Use This?</h4>\n<p>Suitable for adults and teenagers who experience migraines, tension headaches, stress-related headaches, or motion sickness. Also beneficial for those who want a drug-free alternative to pain relief.</p>\n<h4>Restrictions</h4>\n<p>Not a substitute for prescribed medical treatment. If migraines are frequent or severe, consult a neurologist.</p>\n<h4>Precautions / Notes</h4>\n<ul>\n<li>Avoid contact with eyes — roll around, not directly on, the eye socket.</li>\n<li>Do not use it on children under 6 years without medical advice.</li>\n<li>Pregnant or nursing women should consult a doctor before use.</li>\n<li>Perform a patch test before first use if you have sensitive skin.</li>\n<li>Do not ingest.</li>\n</ul>','[{\"label\":\"Available types\",\"value\":\"Bottle, Roll-on\"},{\"label\":\"Available sizes\",\"value\":\"10ml, 30ml\"},{\"label\":\"Category\",\"value\":\"Essential Oils\"},{\"label\":\"Packed & shipped from\",\"value\":\"Ooty, The Nilgiris\"},{\"label\":\"Price\",\"value\":\"Inclusive of GST\"}]',NULL,150.00,160.00,80,1,0,0,0,'2026-11-10 10:16:05','2026-11-10 10:16:05'),(10,2,NULL,'Premium Coffee Powder','premium-coffee-powder',NULL,'Made from the finest robusta coffee beans, this premium blend offers a rich taste and aroma that will awaken your senses. Our coffee powder is perfect for those who want to experience the best quality coffee every morning. Order now and taste the difference. Ingredients Coffee 80% Chicory 20%','<p>Our premium coffee powder is a perfect blend of 80% coffee and 20% chicory that you can enjoy every day.</p>','[{\"label\":\"Available weights\",\"value\":\"250g, 500g\"},{\"label\":\"Category\",\"value\":\"Coffee\"},{\"label\":\"Packed & shipped from\",\"value\":\"Ooty, The Nilgiris\"},{\"label\":\"Price\",\"value\":\"Inclusive of GST\"}]',NULL,225.00,240.00,80,1,0,0,0,'2026-11-10 10:16:05','2026-11-10 10:16:05'),(11,2,NULL,'Strong Coffee Powder','strong-coffee-powder',NULL,'Not only does it provide a rich aroma, but it also rejuvenates your energy for a productive day ahead. Ideal for filter coffee lovers, this strong coffee powder is sure to satisfy your caffeine cravings. Order now and experience the perfect cup of coffee every time.','<p>Indulge in our Strong Coffee Powder – the perfect addition to your morning routine. Made with 70% coffee and 30% Chicory, this blend is sure to provide a bold and robust flavor.</p>','[{\"label\":\"Available weights\",\"value\":\"250g, 500g\"},{\"label\":\"Category\",\"value\":\"Coffee\"},{\"label\":\"Packed & shipped from\",\"value\":\"Ooty, The Nilgiris\"},{\"label\":\"Price\",\"value\":\"Inclusive of GST\"}]',NULL,200.00,240.00,80,1,0,0,0,'2026-11-10 10:16:05','2026-11-10 10:16:05'),(12,4,NULL,'Ooty Varkey Special Round Big','ooty-varkey-special-round-big',NULL,'Perfect for snacking, the Ooty Varkey Special Big Round is a crunchy and satisfying snack that will leave you wanting more. Order now and experience the taste of authentic Ooty cookies with our Ooty Varkey Regular.','<p>The Ooty Varkey Regular is a classic treat from the hills of Nilgiris, brought to you by our online Ooty store. These eggless and vegetarian cookies are made with the finest ingredients, and are a must-try for anyone looking to indulge in the delicious taste of Ooty products.</p>','[{\"label\":\"Available weights\",\"value\":\"500g, 1Kg\"},{\"label\":\"Category\",\"value\":\"Cookies & Bakes\"},{\"label\":\"Packed & shipped from\",\"value\":\"Ooty, The Nilgiris\"},{\"label\":\"Price\",\"value\":\"Inclusive of GST\"}]',NULL,175.00,220.00,80,1,0,0,0,'2026-11-10 10:16:05','2026-11-10 10:16:05'),(13,4,NULL,'Ooty Varkey Square','ooty-varkey-square',NULL,'Perfect for snacking, the Ooty Varkey Regular is a crunchy and satisfying snack that will leave you wanting more. Order now and experience the taste of authentic Ooty cookies with our Ooty Varkey Regular.','<p>The Ooty Varkey Regular is a classic treat from the hills of Nilgiris, brought to you by our online Ooty store. These eggless and vegetarian cookies are made with the finest ingredients, and are a must-try for anyone looking to indulge in the delicious taste of Ooty products.</p>','[{\"label\":\"Ava