INSERT INTO `settings` VALUES ('about_tagline','Bringing the authentic heritage of the Nilgiris to every Indian home.'),('about_values','[{\"title\":\"Authentic\",\"text\":\"Every product is sourced from the Nilgiris and curated by people who live here.\"},{\"title\":\"Fair to growers\",\"text\":\"Our sourcing supports the livelihood of thousands of small farmers and producers.\"},{\"title\":\"Responsible\",\"text\":\"We do business with care for our native place and keep quality intact, always.\"}]'),('announcement','Use code EASY10 for 10% off on orders above ₹1,200'),('business_hours','Mon – Fri: 9:00 am – 8:00 pm · Sat: 11:00 am – 3:00 pm'),('cod_enabled','0'),('contact_address','Ooty Originals, Herdsmen Business Ventures Pvt. Ltd., 10, YBA Building, Church Hill Road, Ooty, The Nilgiris, Tamil Nadu – 643001'),('contact_email','hi@ootyoriginals.in'),('contact_phone','+91 94876 54990'),('contact_whatsapp','+91 94876 54990'),('delivery_info','Packed fresh and shipped from Ooty, The Nilgiris.\nTamil Nadu: next day or within 2 days. Rest of India: 3–7 business days.\nTracking details are shared by email and in My Orders once your order ships.'),('delivery_short','Tamil Nadu in 1–2 days'),('faqs','[{\"q\":\"Where do you source your products from?\",\"a\":\"Directly from local farmers and producers in the Nilgiri Hills. Our sourcing supports the livelihoods of small growers and makers, and every product reflects the craft of the local community.\"},{\"q\":\"How long does delivery take?\",\"a\":\"Within Tamil Nadu we aim to deliver the next day or within 2 days. For other states in India, orders usually arrive in 3–7 business days. You will receive tracking details as soon as your order ships.\"},{\"q\":\"How do you keep products fresh during delivery?\",\"a\":\"We pack every order in Ooty using protective, food-safe packaging that shields it from temperature changes and damage in transit, and we ship with reliable courier partners that prioritise timely delivery.\"},{\"q\":\"What payment methods do you accept?\",\"a\":\"Credit and debit cards, net banking, UPI and popular wallets — all processed securely through Razorpay. Cash on Delivery is available on eligible orders.\"},{\"q\":\"How can I track my order?\",\"a\":\"Open My Orders in your account to see the live status of every order. Once shipped, the courier name and tracking number appear there and are emailed to you.\"},{\"q\":\"What is your return policy?\",\"a\":\"You can return products within 14 days of receipt. Items must be unused, in their original packaging and in the condition you received them. Contact our support team with your order number to start a return.\"},{\"q\":\"Do you offer refunds?\",\"a\":\"Yes. Once we receive and inspect a returned product, the refund is issued to your original payment method, usually within 7 business days. Shipping charges are non-refundable.\"},{\"q\":\"What if I receive a damaged product?\",\"a\":\"Please contact us right away with your order number and a photo of the item. We will arrange a replacement or a refund, whichever you prefer.\"},{\"q\":\"Do you ship internationally?\",\"a\":\"Not yet — we currently deliver across India only. International shipping is something we are working on.\"},{\"q\":\"How can I contact customer support?\",\"a\":\"Email hi@ootyoriginals.in or message us on WhatsApp at +91 94876 54990. We are available Monday to Friday 9 am – 8 pm and Saturday 11 am – 3 pm.\"}]'),('footer_note','Authentic products from the Nilgiris, curated by people who call these hills home.'),('free_shipping_min','0'),('hero_eyebrow','Authentic Nilgiri Products'),('hero_image',''),('hero_slides','[{\"image\":\"/images/col-chocolate.webp\",\"eyebrow\":\"Handmade in Ooty · Pure Cocoa\",\"title\":\"Rich, artisanal homemade chocolates\",\"subtitle\":\"Crafted in small hill-station batches with pure cocoa butter, roasted mountain almonds, and melt-in-mouth fillings.\",\"button_label\":\"Explore Chocolates\",\"button_link\":\"/shop?category=homemade-chocolates\",\"showcase_image\":\"/uploads/products/assorted-homemade-chocolates-1.webp\",\"showcase_badge\":\"🔥 BEST SELLER\",\"showcase_category\":\"Artisanal Hill Chocolates\",\"showcase_title\":\"Assorted Homemade Chocolates\",\"showcase_rating\":\"5.0\",\"showcase_price\":\"₹400\",\"showcase_link\":\"/shop?category=homemade-chocolates\"},{\"image\":\"/images/hero-estate.webp\",\"eyebrow\":\"Authentic Nilgiri Products\",\"title\":\"From the Nilgiri hills to your home\",\"subtitle\":\"Estate-fresh teas, homemade chocolates, pure essential oils and classic Ooty varkey — sourced directly from local growers and makers, packed fresh in Ooty.\",\"button_label\":\"Shop the collection\",\"button_link\":\"/shop\",\"showcase_image\":\"/images/story-tea.webp\",\"showcase_badge\":\"✨ SPECIAL HARVEST\",\"showcase_category\":\"Nilgiri Single Estate Tea\",\"showcase_title\":\"Nilgiri Whole Leaf Black Tea\",\"showcase_rating\":\"4.9\",\"showcase_price\":\"₹260\",\"showcase_link\":\"/shop?category=nilgiri-teas\"},{\"image\":\"/images/col-oils.webp\",\"eyebrow\":\"100% Steam Distilled · Pure & Natural\",\"title\":\"Pure therapeutic hill essential oils\",\"subtitle\":\"Wild Nilgiri eucalyptus, wintergreen and cold-pressed botanical oils distilled fresh for natural healing, pain relief and aromatherapy.\",\"button_label\":\"Discover Essential Oils\",\"button_link\":\"/shop?category=essential-oils\",\"showcase_image\":\"/uploads/products/eucalyptus-oil-1.webp\",\"showcase_badge\":\"🌿 100% PURE\",\"showcase_category\":\"Nilgiri Forest Extracts\",\"showcase_title\":\"Pure Nilgiri Eucalyptus Oil\",\"showcase_rating\":\"4.9\",\"showcase_price\":\"From ₹100\",\"showcase_link\":\"/shop?category=essential-oils\"}]'),('hero_subtitle','Estate-fresh teas, homemade chocolates, pure essential oils and classic Ooty varkey — sourced directly from local growers and makers, packed fresh in Ooty.'),('hero_title','From the Nilgiri hills to your home'),('newsletter_text','New harvests, offers and stories — a few times a month.'),('newsletter_title','Letters from the hills'),('promises','[{\"title\":\"Sourced in the Nilgiris\",\"text\":\"Direct from local growers and makers\"},{\"title\":\"Packed fresh in Ooty\",\"text\":\"Small batches, sealed for freshness\"},{\"title\":\"Delivered across India\",\"text\":\"Tamil Nadu in 1–2 days\"},{\"title\":\"Secure payments\",\"text\":\"UPI, cards and net banking\"}]'),('promo_banner','{\"eyebrow\":\"WELCOME OOTY ORIGINALS\",\"title\":\"TODAY SPECIAL\",\"title_highlight\":\"TEA TIME HAMPER\",\"subtitle\":\"Limits Time Offer · 5 Rare Nilgiri Treasures\",\"text\":\"Experience Nilgiri Cardamom Tea, Fresh Roasted Coffee, Crisp Varkey, Wheat Biscuits & Rich Artisanal Chocolates.\",\"button_label\":\"ORDER NOW\",\"button_link\":\"/shop?category=cookies-bakes\",\"price\":\"₹999\",\"compare_price\":\"₹1,360\",\"badge_text\":\"27% Off\",\"image\":\"/uploads/products/ooty-s-finest-five-tea-time-hamper-1.webp\"}'),('promo_banners','[{\"eyebrow\":\"WELCOME OOTY ORIGINALS\",\"title\":\"TODAY SPECIAL\",\"title_highlight\":\"TEA TIME HAMPER\",\"subtitle\":\"Limits Time Offer · 5 Rare Nilgiri Treasures\",\"text\":\"Experience Nilgiri Cardamom Tea, Fresh Roasted Coffee, Crisp Varkey, Wheat Biscuits & Rich Artisanal Chocolates.\",\"button_label\":\"ORDER NOW\",\"button_link\":\"/shop?category=cookies-bakes\",\"price\":\"₹999\",\"compare_price\":\"₹1,360\",\"badge_text\":\"27% Off\",\"image\":\"/uploads/products/ooty-s-finest-five-tea-time-hamper-1.webp\"}]'),('promo_cards','[{\"eyebrow\":\"ON THIS WEEK\",\"title\":\"ESTATE FRESH\",\"title_highlight\":\"NILGIRI TEAS\",\"subtitle\":\"Limits Time Offer\",\"button_label\":\"ORDER NOW\",\"button_link\":\"/shop?category=nilgiri-teas\",\"badge_text\":\"100%\",\"badge_subtext\":\"PURE\",\"image\":\"/uploads/products/nilgiri-black-tea-150g-1.webp\"},{\"eyebrow\":\"WELCOME OOTY\",\"title\":\"ARTISANAL\",\"title_highlight\":\"CHOCOLATES\",\"subtitle\":\"Limits Time Offer\",\"button_label\":\"ORDER NOW\",\"button_link\":\"/shop?category=homemade-chocolates\",\"badge_text\":\"15%\",\"badge_subtext\":\"OFF\",\"image\":\"/uploads/products/assorted-homemade-chocolates-1.webp\"},{\"eyebrow\":\"ON THIS WEEK\",\"title\":\"PURE NILGIRI\",\"title_highlight\":\"ESSENTIAL OILS\",\"subtitle\":\"Limits Time Offer\",\"button_label\":\"ORDER NOW\",\"button_link\":\"/shop?category=essential-oils\",\"badge_text\":\"TOP\",\"badge_subtext\":\"SELLER\",\"image\":\"/uploads/products/eucalyptus-oil-1.webp\"}]'),('returns_info','Return within 14 days of delivery if the product is unused and in its original packaging.\nDamaged on arrival? Contact us with a photo and we will replace or refund it.'),('returns_short','Within 14 days'),('shipping_fee','0'),('social_facebook','https://www.facebook.com/ootyoriginals'),('social_instagram','https://www.instagram.com/ootyoriginals'),('social_youtube','https://www.youtube.com/@OotyOriginals'),('story_stat','1000s'),('story_stat_text','of small farmers and producers supported across the hills'),('story_text','We are a team of native people who came together to bring authentic, high-quality products from the Nilgiris to homes across the country.\n\nEvery product carries the soul of these hills — grown with integrity, packed with honesty and delivered with pride. Ooty Originals was never just a business. It is a promise to protect and share the heritage of the Nilgiris.'),('story_title','Curated by people who call these hills home');
